# Non-deployable source-membership v1: frozen 20 DEV songs, real C renderer.
# Masks were generated by oracle_source_membership.py with its default latch.
$T = "D:\upmix\tools"
$R = "D:\upmix\runs"
$Mask = "$R\membership\oracle_source_membership_v1"
$Out = "$R\membership\oracle_source_membership_v1_screen"
if (-not (Test-Path "$Mask\report.json")) { throw "membership masks are incomplete" }
$env:CUDA_VISIBLE_DEVICES = '-1'
$HarnessArgs = "--render $T\upmix_render_inj.exe --model $T\hssr_model.bin --guard $T\hssr_guard.bin " +
    "--moisesdb D:\upmix\datasets\moisesdb\moisesdb_v0.1 --split-file D:\upmix\datasets\masknet_cache7\split.json " +
    "--split dev --songs 20 --seed 1 --variant shipped --jobs 2 --mask-dir $Mask " +
    "--oracle-ref $R\masknet-oracle\stems_amp_1.0 --render-extra `"--mask-drive 1.0`""
& "$T\stems_guard.ps1" -Out $Out -Log "$Out.log" -HArgs $HarnessArgs
if (-not (Test-Path "$Out\stems.csv")) { throw "source-membership C screen failed" }
Write-Output "Completed $Out\stems.csv"
